/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: fixture, seed, unsupported, preview, snapshot
 *   Constants: albumId
 *   Variables: mongo, storage, client
 * Tests
 *   - the preview measures exactly the tracks lookup cannot time and writes nothing
 *   - catalog-only previews read no storage, and limits resume after the last reported track
 *   - decoder and storage outages are reported per track without stopping the preview
 * @end-catalog */

/** The Audio duration backfill preview against a disposable replica set and the loopback S3: it reads, measures and never writes. */
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { randomBytes } from 'node:crypto';
import { after, before, beforeEach, test } from 'node:test';
import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { ObjectId } from 'mongodb';
import { getDb } from '../../src/infrastructure/database';
import { ROOM_AUDIO_ANALYSIS_VERSION } from '../../src/models/mediaRepresentation';
import {
    planAudioDurationBackfill, type AudioDurationBackfillDependencies, type AudioDurationBackfillEntry, type AudioDurationBackfillOptions
} from '../../src/services/audio/audioDurationBackfill';
import { probeAudioDurationMs } from '../../src/services/roomAudio/audioDurationProbe';
import { RoomAudioInspectionError } from '../../src/services/roomAudio/roomAudioInspection';
import { startLocalS3 } from '../support/localS3';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';

let mongo: MongoReplicaSetHarness;
let storage: Awaited<ReturnType<typeof startLocalS3>>;
let client: S3Client;

before(async () => {
    mongo = await startMongoReplicaSet('archtree-audio-duration-backfill-test');
    storage = await startLocalS3('audio-duration-backfill');
    client = new S3Client({ endpoint: storage.endpoint, region: 'us-east-1', forcePathStyle: true,
        credentials: { accessKeyId: 'owned-loopback-fixture', secretAccessKey: 'owned-loopback-fixture-secret' }, maxAttempts: 1 });
});
beforeEach(async () => {
    await getDb()!.collection('audioTracks').deleteMany({});
    storage.objects.clear(); storage.requests.length = 0;
});
after(async () => { client?.destroy(); await storage?.stop(); await mongo?.stop(); });

const fixture = (name: string) => readFile(new URL(`../fixtures/room-audio/${name}`, import.meta.url));
const albumId = new ObjectId().toHexString();

/** Uploads bytes through the real SDK and inserts a ready, published track whose representation is built by `representation`. */
const seed = async (bytes: Buffer, fields: Record<string, unknown>,
    representation?: (object: { key: string; etag: string; versionId: string; byteLength: number }) => Record<string, unknown>) => {
    const id = new ObjectId(); const key = `audio/${id.toHexString()}/${new ObjectId().toHexString()}`;
    const uploaded = await client.send(new PutObjectCommand({ Bucket: storage.bucket, Key: key, Body: bytes, ContentType: 'audio/flac' }));
    await getDb()!.collection('audioTracks').insertOne({ _id: id, title: 'Private title', albumId, s3Key: key, mediaType: 'audio',
        uploadStatus: 'ready', publicationStatus: 'ready', duration: '', ...fields,
        ...(representation ? { mediaRepresentation: representation({ key, etag: uploaded.ETag!, versionId: uploaded.VersionId!, byteLength: bytes.length }) } : {}) });
    return { id: id.toHexString(), key };
};
/** The upload-time record of audio rooms reject, before durations were probed. */
const unsupported = (object: { key: string; etag: string; versionId: string; byteLength: number }) => ({
    revision: `mr_${randomBytes(16).toString('hex')}`, objectKey: object.key, byteLength: object.byteLength, durationMs: null,
    seekable: false, format: 'unsupported', etag: object.etag, versionId: object.versionId, analysisVersion: ROOM_AUDIO_ANALYSIS_VERSION
});

const preview = async (options: Partial<AudioDurationBackfillOptions> = {}, overrides: Partial<AudioDurationBackfillDependencies> = {}) => {
    const entries: AudioDurationBackfillEntry[] = [];
    const summary = await planAudioDurationBackfill({ limit: 100, catalogOnly: false, ...options }, {
        database: () => getDb()!, storage: () => client, bucket: storage.bucket, probe: probeAudioDurationMs,
        record: entry => { entries.push(entry); }, ...overrides
    });
    return { entries, summary };
};
const snapshot = () => getDb()!.collection('audioTracks').find({}).sort({ _id: 1 }).toArray();

test('the preview measures exactly the tracks lookup cannot time and writes nothing', async () => {
    const flac = await fixture('tone.flac');
    const analyzed = await seed(flac, { trackNumber: 1, discNumber: 1 }, unsupported);
    const neverAnalyzed = await seed(flac, { trackNumber: 2 });
    await seed(await fixture('cbr.mp3'), {}, object => ({ ...unsupported(object), durationMs: 2000, seekable: true, format: 'mp3' }));
    await seed(flac, { duration: '04:05' });
    const corrupt = await seed(Buffer.from('not actually decoded audio data'), {}, unsupported);
    const replaced = await seed(flac, {}, unsupported);
    await client.send(new PutObjectCommand({ Bucket: storage.bucket, Key: replaced.key, Body: await fixture('tone.aiff') }));
    const malformed = await seed(flac, {}, object => ({ ...unsupported(object), etag: 'unquoted' }));
    const before = await snapshot(); const seeded = storage.requests.length;

    const { entries, summary } = await preview();
    assert.deepEqual(entries.map(entry => [entry.mediaTrackId, entry.representation, entry.result, entry.reason, entry.durationMs, entry.set]), [
        [analyzed.id, 'stored', 'wouldUpdate', null, 2000, { 'mediaRepresentation.durationMs': 2000, duration: '00:02' }],
        [neverAnalyzed.id, 'missing', 'wouldUpdate', null, 2000, { duration: '00:02' }],
        [corrupt.id, 'stored', 'unprobeable', null, null, {}],
        [replaced.id, 'stored', 'stale', 'source_changed', null, {}],
        [malformed.id, 'invalid', 'wouldUpdate', null, 2000, { duration: '00:02' }]
    ]);
    assert.deepEqual([entries[0].albumId, entries[0].discNumber, entries[0].trackNumber, entries[1].discNumber], [albumId, 1, 1, null]);
    assert.deepEqual(summary, { type: 'summary', dryRun: true, finished: true, resumeAfter: null, scanned: 7, candidates: 5,
        counts: { wouldUpdate: 3, unprobeable: 1, stale: 1 } });
    assert.ok(!JSON.stringify(entries).includes('Private title') && !JSON.stringify(entries).includes(analyzed.key), 'Rows omit titles and keys.');
    assert.deepEqual(await snapshot(), before, 'A preview never writes to the database.');
    const reads = storage.requests.slice(seeded);
    assert.ok(reads.length === 5 && reads.every(request => request.method === 'GET'), 'A preview only reads storage.');
    assert.equal(reads[0].ifMatch, (before[0].mediaRepresentation as { etag: string }).etag, 'A stored representation pins its read.');
});

test('catalog-only previews read no storage, and limits resume after the last reported track', async () => {
    const flac = await fixture('tone.flac');
    const ids = [];
    for (let index = 0; index < 3; index += 1) ids.push((await seed(flac, {}, unsupported)).id);
    const seeded = storage.requests.length;
    const listed = await preview({ catalogOnly: true });
    assert.deepEqual(listed.entries.map(entry => [entry.result, entry.durationMs, entry.set]), Array(3).fill(['listed', null, {}]));
    assert.equal(storage.requests.length, seeded);

    const first = await preview({ limit: 2 });
    assert.deepEqual(first.entries.map(entry => entry.mediaTrackId), ids.slice(0, 2));
    assert.deepEqual([first.summary.finished, first.summary.resumeAfter], [false, ids[1]]);
    const rest = await preview({ limit: 2, after: first.summary.resumeAfter! });
    assert.deepEqual(rest.entries.map(entry => entry.mediaTrackId), ids.slice(2));
    assert.deepEqual([rest.summary.finished, rest.summary.resumeAfter], [true, null]);
});

test('decoder and storage outages are reported per track without stopping the preview', async () => {
    const flac = await fixture('tone.flac');
    const missingObject = await seed(flac, {});
    storage.objects.delete(missingObject.key);
    const decoderDown = await seed(flac, {}, unsupported);
    const { entries } = await preview({}, { probe: async () => { throw new RoomAudioInspectionError('decoder_unavailable'); } });
    assert.deepEqual(entries.map(entry => [entry.mediaTrackId, entry.result, entry.reason]), [
        [missingObject.id, 'stale', 'source_changed'], [decoderDown.id, 'failed', 'decoder_unavailable']
    ]);
    const unreachable = await preview({}, { storage: () => new S3Client({ endpoint: 'http://127.0.0.1:9', region: 'us-east-1', forcePathStyle: true,
        credentials: { accessKeyId: 'owned-loopback-fixture', secretAccessKey: 'owned-loopback-fixture-secret' }, maxAttempts: 1 }) });
    assert.deepEqual(unreachable.entries.map(entry => [entry.result, entry.reason]), Array(2).fill(['failed', 'storage_unavailable']));
});
